import base64
import sys
import codecs

def try_decodings(filename):
    with open(filename, 'rb') as f:
        data = f.read()

    # Try various encodings
    print("ASCII:")
    try:
        print(data.decode('ascii')[:100])
    except:
        print("Not valid ASCII")

    print("\nBase32:")
    try:
        decoded = base64.b32decode(data)
        print(decoded[:100])
    except:
        print("Not valid base32")

    print("\nROT13:")
    try:
        decoded = codecs.decode(data.decode('ascii'), 'rot13')
        print(decoded[:100])
    except:
        print("Not valid ROT13")

    # Look for coordinate-like patterns in ASCII
    ascii_text = ''
    try:
        ascii_text = data.decode('ascii')
        coords = []
        for part in ascii_text.split():
            try:
                num = float(part)
                coords.append(num)
            except:
                pass
        if coords:
            print("\nPossible numeric values found:")
            print(coords[:10])
    except:
        pass

    # Check for repetitive patterns
    try:
        chunks = [ascii_text[i:i+2] for i in range(0, len(ascii_text), 2)]
        pattern_count = {}
        for chunk in chunks:
            if chunk in pattern_count:
                pattern_count[chunk] += 1
            else:
                pattern_count[chunk] = 1

        # Get most common patterns
        common_patterns = sorted(pattern_count.items(), key=lambda x: x[1], reverse=True)[:10]
        print("\nMost common 2-char patterns:")
        print(common_patterns)
    except:
        print("Could not analyze patterns")

