import bz2
import struct

def extract_bits(data):
    """Extract bits from potential IEEE 754 data"""
    for i in range(len(data)-7):
        try:
            # Try as double
            value = struct.unpack('d', data[i:i+8])[0]
            binary = bin(struct.unpack('Q', data[i:i+8])[0])[2:].zfill(64)

            # Extract components
            sign = int(binary[0])
            exp = int(binary[1:12], 2)
            mantissa = int(binary[12:], 2)

            # Check if this could be part of text
            try:
                # Try different combinations of bits for text
                text_attempts = [
                    binary,  # All bits
                    binary[::8],  # Every 8th bit
                    bin(exp)[2:].zfill(11),  # Just exponent bits
                    bin(mantissa)[2:],  # Just mantissa bits
                ]

                for bits in text_attempts:
                    # Try to convert bits to ASCII
                    for j in range(len(bits)-7):
                        try:
                            chunk = bits[j:j+8]
                            char = chr(int(chunk, 2))
                            if 32 <= ord(char) <= 126:  # Printable ASCII
                                # If we find 'csaw', print a wider window
                                if 'csaw' in bits[j:j+40].lower():
                                    print(f"Potential flag at offset {i}, using bits {bits[j:j+40]}")
                        except:
                            continue
            except:
                continue

            # Also try raw bytes sequence
            try:
                text = data[i:i+32].decode('utf-8')
                if 'csaw' in text.lower():
                    print(f"Raw text found at {i}: {text}")
            except:
                pass

        except:
            continue

def analyze_file(filename):
    with open(filename, 'rb') as f:
        data = f.read()

    try:
        # Try to decompress first
        decompressed = bz2.decompress(data)
        print("BZip2 decompressed size:", len(decompressed))
        extract_bits(decompressed)
    except:
        print("Not BZip2 or decompression failed")
        extract_bits(data)

